<body>
<?php if($useSiteShell): ?><div class="shell"><?php echo $siteHeaderHtml; ?></div><?php else: ?><header class="fallback-header"><div class="wrap"><a class="brand" href="<?php echo e($archiveUrl($contentType)); ?>"><?php echo e($website->name); ?></a><nav><a href="<?php echo e($archiveUrl($contentType)); ?>"><?php echo e($contentType->name); ?></a></nav></div></header><?php endif; ?>

<?php if($viewMode === 'archive'): ?>
<section class="content-hero"><div class="wrap"><div class="kicker"><?php echo e($contentType->singular_name); ?> archive</div><h1><?php echo e($contentType->name); ?></h1><p class="hero-copy"><?php echo e($contentType->description ?: 'Explore the latest '.$contentType->name.'.'); ?></p><?php if($categories->isNotEmpty() || $tags->isNotEmpty()): ?><div class="filters"><a class="pill <?php echo e(!$activeCategory && !$activeTag ? 'active' : ''); ?>" href="<?php echo e($archiveUrl($contentType)); ?>">All</a><?php $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $category): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><a class="pill <?php echo e($activeCategory === $category ? 'active' : ''); ?>" href="<?php echo e($archiveUrl($contentType)); ?>?category=<?php echo e(rawurlencode($category)); ?>"><?php echo e($category); ?></a><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?> <?php $__currentLoopData = $tags->take(6); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $tag): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><a class="pill <?php echo e($activeTag === $tag ? 'active' : ''); ?>" href="<?php echo e($archiveUrl($contentType)); ?>?tag=<?php echo e(rawurlencode($tag)); ?>">#<?php echo e($tag); ?></a><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php endif; ?></div></section>
<section class="archive"><div class="wrap"><?php if($entries->isEmpty()): ?><div class="empty">No published <?php echo e(strtolower($contentType->name)); ?> yet.</div><?php else: ?><div class="grid"><?php $__currentLoopData = $entries; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $entry): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><article class="card"><a class="card-media" href="<?php echo e($entryUrl($contentType,$entry)); ?>"><?php if($entry->featured_image_url): ?><img src="<?php echo e($assetUrl($entry->featured_image_url)); ?>" alt="<?php echo e($entry->title); ?>"><?php endif; ?></a><div class="card-body"><div class="meta"><?php echo e($entry->category ?: $contentType->singular_name); ?><?php if($entry->is_featured): ?> · Featured <?php endif; ?></div><h2><a href="<?php echo e($entryUrl($contentType,$entry)); ?>"><?php echo e($entry->title); ?></a></h2><p><?php echo e($entry->excerpt); ?></p><a class="read" href="<?php echo e($entryUrl($contentType,$entry)); ?>">Read more →</a></div></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php endif; ?></div></section>
<?php else: ?>
<section class="entry-template-runtime"><?php echo $renderedTemplateMarkup ?? ''; ?></section>
<?php endif; ?>

<?php if($useSiteShell): ?><div class="shell"><?php echo $siteFooterHtml; ?></div><?php else: ?><footer class="fallback-footer"><div class="wrap"><strong><?php echo e($website->name); ?></strong><span>Powered by Cosmic CMS</span></div></footer><?php endif; ?>
